def hoehe(k):
    if k is None:
        return -1
    return 1 + max(hoehe(k.links),
                   hoehe(k.rechts))

def anzahl(k):
    if k is None:
        return 0
    return (1 + anzahl(k.links)
              + anzahl(k.rechts))

print(hoehe(a))    # 2
print(anzahl(a))   # 6
